#!/bin/bash

################################################################################
# STAGE 09: metaQUAST - Bin quality assessment
################################################################################
#
# Input variables (from SLURM template):
#   - SAMPLE              : Sample name
#   - NUM_THREADS         : Number of CPU threads
#   - REASSEMBLED_BINS_DIR: Directory containing reassembled and renamed bins
#   - QUAST_BINS_OUT      : Output directory for metaQUAST results
#   - METAQUAST_REFS_FILE : References list generated by GTDB-Tk in STAGE_08
#   - KNEADDATA_OUT       : Directory containing decontaminated paired reads
#   - STATUS_DIR          : Path to status directory
#
# Output:
#   - metaQUAST report : ${QUAST_BINS_OUT}/report.html
#   - ${STATUS_DIR}/${SAMPLE}.resume updated to STAGE_10
#
# Note:
#   - METAQUAST_REFS_FILE is generated by GTDB-Tk bin renaming in STAGE_08
#     and must exist before this stage runs
#   - If no bins exist the glob will fail and the ERR trap will fire
#
################################################################################

echo "$(date): [STAGE 09/24] Starting metaQUAST bin assessment for ${SAMPLE}..."
echo "  Bins      : ${FINAL_BINS_DIR}/*.fa"
echo "  References: ${METAQUAST_REFS_FILE}"
echo "  Reads R1  : ${KNEADDATA_OUT}/out.${SAMPLE}.R1_kneaddata_paired_1.fastq.gz"
echo "  Reads R2  : ${KNEADDATA_OUT}/out.${SAMPLE}.R1_kneaddata_paired_2.fastq.gz"
echo "  Output    : ${QUAST_BINS_OUT}"

conda activate quast-env

# Use value from SLURM template; fall back safely if Stage 08 was skipped
METAQUAST_REFS_FILE="${METAQUAST_REFS_FILE:-${FINAL_BINS_DIR}/metaquast_references.txt}"

if [ -s "${METAQUAST_REFS_FILE}" ]; then
    echo "$(date): Using references list: ${METAQUAST_REFS_FILE}"
    metaquast.py "${FINAL_BINS_DIR}/"*.fa \
        -o "${QUAST_BINS_OUT}/" \
        --threads ${NUM_THREADS} \
        --references-list "${METAQUAST_REFS_FILE}" \
        --pe1 "${KNEADDATA_OUT}/out.${SAMPLE}.R1_kneaddata_paired_1.fastq.gz" \
        --pe2 "${KNEADDATA_OUT}/out.${SAMPLE}.R1_kneaddata_paired_2.fastq.gz" \
        --max-ref-number 0
else
    echo "$(date): References file not found or empty, running without references."
    metaquast.py "${FINAL_BINS_DIR}/"*.fa \
        -o "${QUAST_BINS_OUT}/" \
        --threads ${NUM_THREADS} \
        --pe1 "${KNEADDATA_OUT}/out.${SAMPLE}.R1_kneaddata_paired_1.fastq.gz" \
        --pe2 "${KNEADDATA_OUT}/out.${SAMPLE}.R1_kneaddata_paired_2.fastq.gz" \
        --max-ref-number 0
fi

conda deactivate || true

echo "STAGE_10" > "${STATUS_DIR}/${SAMPLE}.resume"
echo "$(date): [STAGE 09/24] metaQUAST bin assessment complete."
